import json

KNOWN_TICKETS = {"T-100", "T-101"}
ALLOWED = {"ticket_id", "priority", "summary"}

def validate(raw):
    try:
        data = json.loads(raw)
    except json.JSONDecodeError:
        return "reject: not JSON"
    if not isinstance(data, dict) or set(data) != ALLOWED:
        return f"reject: fields {sorted(set(data) if isinstance(data, dict) else [])}"
    if not isinstance(data["priority"], int) or not 1 <= data["priority"] <= 5:
        return "reject: priority out of range"
    if data["ticket_id"] not in KNOWN_TICKETS:           # verify against real data.
        return "reject: unknown ticket"
    return "accept"

print(validate('{"ticket_id": "T-100", "priority": 2, "summary": "login fails"}'))   # accept
print(validate('{"ticket_id": "T-100", "priority": 11, "summary": "x"}'))          # range
print(validate('{"ticket_id": "T-9", "priority": 3, "summary": "x", "refund": true}'))  # fields
```

